97	// A single line item in the honest final summary.
98	export type MigrationStepResult = {
99	  step: string;
100	  // running  = verified running on the target
101	  // copied   = placed on the target but NOT verified running (may need a manual step)
102	  // failed   = attempted, failed (reason in detail) — did NOT fail the migration
103	  // skipped  = nothing to do
104	  status: "running" | "copied" | "failed" | "skipped";
105	  detail: string;
106	};
107	
108	export type RealMigrationSummary = {
109	  results: MigrationStepResult[];
110	  verifiedRunning: string[];
111	  needsAttention: string[];
112	};
113	
114	export type RealMigrationInput = {
115	  migration: MigrationRow;
116	  target: TargetServer | null;
117	  items: Items;
118	  report: ReportFn;
119	};
