121	// ---- Timeouts -------------------------------------------------------------
122	const CONNECT_TIMEOUT_MS = 20_000;
123	const SETUP_TIMEOUT_MS = 60_000; // small writes, checks
124	const INSTALL_TIMEOUT_MS = 10 * 60_000; // package installs (apt/dnf can be slow)
125	const TRANSFER_TIMEOUT_MS = Number(process.env.MIGRATE_EXEC_TIMEOUT_MS ?? 45 * 60_000); // rsync/dump/import
126	const GiB = 1024 ** 3;
127	
128	// ---- Strict allowlist validators (throw/reject on any violation) ----------
129	// Charsets below are deliberately shell-inert: no quotes, spaces, metachars or
130	// newlines. Validated values are therefore safe to interpolate into a command.
131	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
132	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
133	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
134	const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
135	const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/; // absolute path, safe charset
136	// Docker volume name (docker's own charset) and systemd unit name — shell-inert.
137	const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
138	const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;
139	
140	// Top-level system locations we refuse to overwrite on the target even if a
141	// (validated) path points at one — a lift-and-shift must never clobber the new
142	// server's own OS. Docker volumes/state are handled by their dedicated steps.
143	const UNSAFE_PREFIXES = [
144	  "/bin", "/sbin", "/usr", "/lib", "/lib64", "/etc/systemd", "/proc", "/sys",
145	  "/dev", "/run", "/boot", "/var/lib/docker",
146	];
147	const UNSAFE_EXACT = new Set(["/", "/etc", "/var", "/var/lib", "/usr", "/home", "/root/.ssh"]);
148	
149	function assert(cond: unknown, msg: string): asserts cond {
150	  if (!cond) throw new Error(msg);
151	}
152	
153	function validHost(h: string): boolean {
154	  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
155	}
156	
157	function validPath(p: string): boolean {
158	  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
159	}
160	
161	/** A validated path we are willing to rsync directly onto the target's real fs. */
162	function safeCopyTarget(p: string): boolean {
163	  if (!validPath(p)) return false;
164	  if (UNSAFE_EXACT.has(p)) return false;
165	  for (const pre of UNSAFE_PREFIXES) if (p === pre || p.startsWith(pre + "/")) return false;
166	  return true;
167	}
168	
169	/** dirname of a validated absolute path (both inputs/outputs are shell-inert). */
170	function parentDir(p: string): string {
171	  const i = p.lastIndexOf("/");
172	  return i <= 0 ? "/" : p.slice(0, i);
173	}
