175	// ---- SSH plumbing ---------------------------------------------------------
176	function execRemote(
177	  conn: Client,
178	  cmd: string,
179	  timeoutMs: number
180	): Promise<{ code: number; stdout: string; stderr: string }> {
181	  return new Promise((resolve, reject) => {
182	    conn.exec(cmd, (err, stream: ClientChannel) => {
183	      if (err) return reject(err);
184	      let stdout = "";
185	      let stderr = "";
186	      const timer = setTimeout(() => {
187	        try {
188	          stream.close();
189	        } catch {
190	          /* ignore */
191	        }
192	        reject(new Error("remote command timed out"));
193	      }, timeoutMs);
194	      stream
195	        .on("close", (code: number) => {
196	          clearTimeout(timer);
197	          resolve({ code: code ?? 0, stdout, stderr });
198	        })
199	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
200	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
201	    });
202	  });
203	}
204	
205	/** Write bytes to a remote file over SFTP with a fixed 0600 mode (no shell). */
206	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
207	  return new Promise((resolve, reject) => {
208	    const ws = sftp.createWriteStream(path, { mode: 0o600 });
209	    ws.on("close", () => resolve());
210	    ws.on("error", (e: Error) => reject(e));
211	    ws.end(Buffer.from(content, "utf8"));
212	  });
213	}
214	
215	function connectTarget(server: TargetServer): Promise<{ conn: Client; sftp: SFTPWrapper }> {
216	  return new Promise((resolve, reject) => {
217	    const target = connectionTarget(server as any);
218	    if (!target) return reject(new Error("target server is not reachable yet — connection details are pending"));
219	    const password = serverRootPassword(server);
220	    if (!password) return reject(new Error("target server has no root password on record"));
221	    const conn = new Client();
222	    conn.on("ready", () => {
223	      conn.sftp((err, sftp) => {
224	        if (err) return reject(err);
225	        resolve({ conn, sftp });
226	      });
227	    });
228	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
229	    conn.connect({
230	      host: target.host,
231	      port: target.port,
232	      username: "root",
233	      password,
234	      readyTimeout: CONNECT_TIMEOUT_MS,
235	    });
236	  });
237	}
