239	// ---- Prerequisite install (FIXED allowlist — never source-supplied) -------
240	// `mysql`        → MariaDB server (the MariaDB path, and the transparent fallback).
241	// `mysql_oracle` → Oracle MySQL server (installed when the source runs Oracle MySQL,
242	//                  so the restore is a clean same-engine import). Every package
243	//                  string below is a compile-time constant; the CHOICE between keys
244	//                  comes from a validated detected enum, never a source-supplied string.
245	type PkgKey = "docker" | "mysql" | "mysql_oracle" | "postgresql" | "nginx" | "apache" | "nodejs" | "python3";
246	
247	// Command that succeeds iff the package's main binary is already present.
248	const PKG_CHECK: Record<PkgKey, string> = {
249	  docker: "command -v docker >/dev/null 2>&1",
250	  mysql: "command -v mysql >/dev/null 2>&1 || command -v mariadb >/dev/null 2>&1",
251	  mysql_oracle: "command -v mysqld >/dev/null 2>&1 || command -v mysql >/dev/null 2>&1",
252	  postgresql: "command -v psql >/dev/null 2>&1",
253	  nginx: "command -v nginx >/dev/null 2>&1",
254	  apache: "command -v apache2 >/dev/null 2>&1 || command -v httpd >/dev/null 2>&1",
255	  nodejs: "command -v node >/dev/null 2>&1",
256	  python3: "command -v python3 >/dev/null 2>&1",
257	};
258	// Debian/Ubuntu (apt) package strings — the primary target for Nxeon servers.
259	const PKG_APT: Record<PkgKey, string> = {
260	  docker: "docker.io docker-compose-plugin",
261	  mysql: "mariadb-server mariadb-client",
262	  mysql_oracle: "mysql-server mysql-client",
263	  postgresql: "postgresql",
264	  nginx: "nginx",
265	  apache: "apache2",
266	  nodejs: "nodejs npm",
267	  python3: "python3 python3-pip",
268	};
269	// RHEL/Fedora (dnf/yum) fallback package strings.
270	const PKG_DNF: Record<PkgKey, string> = {
271	  docker: "docker docker-compose-plugin",
272	  mysql: "mariadb-server mariadb",
273	  mysql_oracle: "mysql-server mysql",
274	  postgresql: "postgresql-server postgresql",
275	  nginx: "nginx",
276	  apache: "httpd",
277	  nodejs: "nodejs npm",
278	  python3: "python3 python3-pip",
279	};
280	// A friendly label for the log/summary.
281	const PKG_LABEL: Record<PkgKey, string> = {
282	  docker: "Docker Engine + compose",
283	  mysql: "MariaDB server",
284	  mysql_oracle: "MySQL server (Oracle)",
285	  postgresql: "PostgreSQL server",
286	  nginx: "nginx",
287	  apache: "Apache",
288	  nodejs: "Node.js",
289	  python3: "Python 3 + pip",
290	};
291	
292	/**
293	 * Idempotently ensure each allowlisted package is present on the target. Runs
294	 * `apt-get update` once, then for each key: skip if the check passes, else try
295	 * apt → dnf → yum with the FIXED package string. Returns which were newly
296	 * installed / already present / failed. Never throws (best-effort per package).
297	 */
298	async function ensurePackages(
299	  conn: Client,
300	  keys: PkgKey[]
301	): Promise<{ key: PkgKey; ok: boolean; already: boolean; err?: string }[]> {
302	  const out: { key: PkgKey; ok: boolean; already: boolean; err?: string }[] = [];
303	  if (keys.length === 0) return out;
304	  // Refresh apt metadata once (best-effort; ignored on non-apt systems).
305	  await execRemote(conn, `apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => {});
306	  for (const key of keys) {
307	    const already = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((r) => r.code === 0).catch(() => false);
308	    if (already) {
309	      out.push({ key, ok: true, already: true });
310	      continue;
311	    }
312	    // All three package strings are compile-time constants from the allowlist.
313	    const install =
314	      `DEBIAN_FRONTEND=noninteractive apt-get install -y ${PKG_APT[key]} ` +
315	      `|| dnf install -y ${PKG_DNF[key]} ` +
316	      `|| yum install -y ${PKG_DNF[key]}`;
317	    const r = await execRemote(conn, install, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
318	    const nowPresent = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
319	    if (nowPresent) {
320	      out.push({ key, ok: true, already: false });
321	    } else {
322	      const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
323	      out.push({ key, ok: false, already: false, err: tail || `install exit ${r.code}` });
324	    }
325	  }
326	  return out;
327	}
