329	// ---- Plan derivation (prefer explicit items, re-validate everything) ------
330	function derivePlan(items: Items) {
331	  const scan = items.scan ?? {};
332	
333	  // Engines to dump: explicit dbEngines, else engines the scan marked present.
334	  const engineSet = new Set<string>();
335	  for (const e of items.dbEngines ?? []) engineSet.add(e);
336	  if (engineSet.size === 0) for (const e of scan.engines ?? []) if (e?.present && e.engine) engineSet.add(e.engine);
337	  const dbEngines = [...engineSet].filter((e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres");
338	
339	  // Which MySQL-family engine to install on the target, from the DETECTED variant:
340	  // Oracle MySQL → mysql-server (clean same-engine); MariaDB (or undeterminable) →
341	  // mariadb-server (the existing safe default). This is a validated enum, never a
342	  // source string; it only selects a fixed package-allowlist KEY.
343	  const mysqlDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "mysql");
344	  const mysqlVariant: "mysql" | "mariadb" = mysqlDetail?.variant === "mysql" ? "mysql" : "mariadb";
345	  const mysqlVersion: string | null = mysqlDetail?.version ?? null;
346	  const pgDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "postgres");
347	  const pgVersion: string | null = pgDetail?.version ?? null;
348	
349	  const dockerVolumes = [...new Set(items.dockerVolumes ?? [])].filter((v) => VOLNAME_RE.test(v)).slice(0, 60);
350	  const composeDirs = [...new Set(items.composeDirs ?? [])].filter((p) => validPath(p)).slice(0, 40);
351	  const verifyPorts = [...new Set((items.verifyPorts ?? []).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22))].slice(0, 60);
352	  const hasContainers = !!items.hasContainers || (scan.containers?.length ?? 0) > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
353	  const webServers = [...new Set(items.webServers ?? [])].filter((w): w is "nginx" | "apache" => w === "nginx" || w === "apache");
354	  const runtimes = [...new Set(items.runtimes ?? [])].filter((r): r is "nodejs" | "python3" => r === "nodejs" || r === "python3");
355	  const services = [...new Set((scan.services ?? []).map((s) => s?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 30);
356	  const containers = (scan.containers ?? [])
357	    .map((c) => ({
358	      name: String(c?.name ?? ""),
359	      image: String(c?.image ?? ""),
360	      ports: String(c?.ports ?? ""),
361	      mounts: Array.isArray(c?.mounts) ? c!.mounts!.map((m) => String(m)) : [],
362	    }))
363	    .slice(0, 30);
364	
365	  const prereqs: PkgKey[] = [];
366	  // Install the engine variant that MATCHES the source (Oracle MySQL vs MariaDB).
367	  if (dbEngines.includes("mysql")) prereqs.push(mysqlVariant === "mysql" ? "mysql_oracle" : "mysql");
368	  if (dbEngines.includes("postgres")) prereqs.push("postgresql");
369	  if (hasContainers) prereqs.push("docker");
370	  for (const w of webServers) prereqs.push(w === "nginx" ? "nginx" : "apache");
371	  for (const rt of runtimes) prereqs.push(rt);
372	
373	  return { dbEngines, mysqlVariant, mysqlVersion, pgVersion, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes, services, containers, prereqs };
374	}
375	
376	// ---------------------------------------------------------------------------
377	
378	/**
379	 * Perform a real lift-and-shift migration. Throws only on a FATAL setup error
380	 * (validation / target connect); every migration sub-step is best-effort and
381	 * records its outcome in the returned summary instead of aborting the run.
382	 */
383	export async function runRealMigration(input: RealMigrationInput): Promise<RealMigrationSummary> {
384	  const { migration, target, items, report } = input;
385	  assert(target, "target server row not found");
386	
387	  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
388	  const host = migration.sourceHost;
389	  const port = migration.sourcePort;
390	  const user = migration.sourceUser;
391	  assert(validHost(host), "source host is not a valid hostname or IP address");
392	  assert(Number.isInteger(port) && port >= 1 && port <= 65535, "source SSH port is out of range");
393	  assert(USER_RE.test(user), "source username contains unsupported characters");
394	
395	  const rawPaths = (items.paths ?? []).map((p) => p.trim()).filter(Boolean);
396	  for (const p of rawPaths) assert(validPath(p), `unsupported file path: ${p}`);
397	  // Direct-to-real-path copy: refuse to overwrite the target's own OS locations.
398	  const paths = rawPaths.filter(safeCopyTarget);
399	
400	  const plan = derivePlan(items);
401	  for (const p of plan.composeDirs) assert(safeCopyTarget(p), `unsupported compose dir: ${p}`);
402	
403	  assert(paths.length || plan.dbEngines.length || plan.composeDirs.length || plan.dockerVolumes.length, "nothing selected to migrate");
404	
405	  // Root-vs-sudo prefix for privileged commands ON THE SOURCE (constant strings).
406	  const priv = user === "root" ? "" : "sudo -n ";
407	
408	  // ---- 2. Decrypt the ONE secret we still need (source SSH password) ------
409	  const sshPass = decryptSecret(migration.sourcePasswordEnc);
410	  assert(sshPass, "source SSH password is missing or could not be decrypted");
411	
412	  // ---- 3. Connect to the TARGET (our own server) --------------------------
413	  await report(6, "Connecting…", "Connecting to your Nxeon server to prepare the lift-and-shift.");
414	  const { conn, sftp } = await connectTarget(target!);
415	
416	  const work = `/root/nxeon-migrations/${migration.id}`;
417	  const passFile = `${work}/ssh.pass`;
418	  const knownHosts = `${work}/known_hosts`;
419	  const sshOpts =
420	    `-p ${port} -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=${knownHosts} ` +
421	    `-o ConnectTimeout=25 -o PreferredAuthentications=password -o PubkeyAuthentication=no`;
422	  const srcSpec = `${user}@${host}`;
423	  // rsync pull from the source over the sshpass-driven ssh (used everywhere below).
424	  const rsyncPull = (remotePath: string, localParent: string) =>
425	    `sshpass -f ${passFile} rsync -az --numeric-ids --timeout=1200 -e 'ssh ${sshOpts}' ${srcSpec}:${remotePath} ${localParent}/`;
426	  // Run a fixed command ON THE SOURCE and capture its output on the target.
427	  const onSource = (cmd: string) => `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} '${cmd}'`;
428	
429	  const results: MigrationStepResult[] = [];
430	  const verifiedRunning: string[] = [];
431	  const needsAttention: string[] = [];
432	  const push = (r: MigrationStepResult) => {
433	    results.push(r);
434	    if (r.status === "running") verifiedRunning.push(r.step);
435	    else if (r.status === "copied" || r.status === "failed") needsAttention.push(`${r.step} — ${r.detail}`);
436	  };
437	
438	  try {
439	    // ---- 4. Prepare the target: transfer tools + work dir + secret file ----
440	    await report(10, "Preparing…", "Ensuring transfer tools (rsync, sshpass) are present on the target.");
441	    await execRemote(
442	      conn,
443	      `command -v rsync >/dev/null 2>&1 && command -v sshpass >/dev/null 2>&1 || ` +
444	        `{ (apt-get update -y && apt-get install -y rsync sshpass) || (dnf install -y rsync sshpass) || (yum install -y rsync sshpass); }`,
445	      INSTALL_TIMEOUT_MS
446	    );
447	    const tools = await execRemote(conn, `command -v rsync && command -v sshpass`, SETUP_TIMEOUT_MS);
448	    assert(tools.code === 0, "could not install rsync/sshpass on the target server");
449	
450	    await execRemote(
451	      conn,
452	      `mkdir -p ${work}/dumps && chmod 700 ${work} && touch ${knownHosts} && chmod 600 ${knownHosts}`,
453	      SETUP_TIMEOUT_MS
454	    );
455	    // Write the source SSH password to a 0600 file over SFTP (never a shell arg).
